import { useCallback, useEffect, useRef, useState } from 'react'
import { Card, CardContent } from '@/components/ui/card'
import { Input } from '@/components/ui/input'

// ============================================================================
// Types
// ============================================================================

/** Compact customer shape returned by GET /customers (search response). */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

interface CustomerSearchResponse {
  customers: CustomerSelectorItem[]
}

// ============================================================================
// Props
// ============================================================================

export interface CustomerSelectorProps {
  /** Currently selected customer id (null = walk-in/anonymous). */
  customerId?: string | null
  /** Called when user selects a customer or chooses walk-in. */
  onSelect: (id: string | null) => void
  /** Whether a customer must be selected (walk-in not allowed). */
  required?: boolean
}

// ============================================================================
// Debounce hook — minimal inline implementation (250ms)
// ============================================================================

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delayMs)
    return () => clearTimeout(timer)
  }, [value, delayMs])

  return debouncedValue
}

// ============================================================================
// Component — Customer Selector (autocomplete input)
// ============================================================================

export function CustomerSelector({
  customerId = null,
  onSelect,
  required = false,
}: CustomerSelectorProps) {
  // Search state
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<CustomerSelectorItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  // Cached selected customer (fetched on mount if customerId is set)
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerSelectorItem | null>(null)

  // Debounced query (250ms delay before API call)
  const debouncedQuery = useDebounce(query, 250)

  // Refs for keyboard navigation and click-outside detection
  const inputRef = useRef<HTMLInputElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // ── Fetch selected customer on mount (if customerId is set) ──────

  useEffect(() => {
    if (!customerId) return

    let cancelled = false

    async function fetchSelectedCustomer() {
      try {
        const response = await fetch('/api/customers')
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            const found = data.customers.find((c) => c.id === customerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }

    fetchSelectedCustomer()
    return () => { cancelled = true }
  }, [customerId])

  // ── Fetch customers on debounced query change ────────────────────

  useEffect(() => {
    // No search term → clear results, close dropdown
    if (!debouncedQuery || debouncedQuery.trim() === '') {
      setResults([])
      setIsOpen(false)
      return
    }

    let cancelled = false

    async function fetchCustomers() {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/customers?search=${encodeURIComponent(debouncedQuery.trim())}`)
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            setResults(data.customers.slice(0, 20))
            setIsOpen(true)
            setHighlightIndex(-1)
          }
        } else {
          if (!cancelled) {
            setResults([])
            setIsOpen(false)
          }
        }
      } catch {
        // Silently fail — walk-in is always available
        if (!cancelled) {
          setResults([])
          setIsOpen(false)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchCustomers()
    return () => { cancelled = true }
  }, [debouncedQuery])

  // ── Click-outside handler — close dropdown when clicking outside ─

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current && !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current && !inputRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ── Select a customer ────────────────────────────────────────────

  const handleSelectCustomer = useCallback((id: string | null) => {
    onSelect(id)
    setIsOpen(false)
    if (id === null) {
      // Reset to walk-in — clear input
      setQuery('')
      setResults([])
    }
  }, [onSelect])

  // ── Keyboard navigation ──────────────────────────────────────────

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen || results.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightIndex((prev) => Math.min(prev + 1, results.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (highlightIndex >= 0 && highlightIndex < results.length) {
          handleSelectCustomer(results[highlightIndex].id)
        } else if (results.length === 1) {
          // Auto-select single result
          handleSelectCustomer(results[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setIsOpen(false)
        inputRef.current?.blur()
        break
    }
  }, [isOpen, results, highlightIndex, handleSelectCustomer])

  // ── Render helpers ───────────────────────────────────────────────

  // Prefer cached selected customer; fall back to searching in results
  const displaySelectedCustomer = selectedCustomerCache ?? results.find((c) => c.id === customerId) ?? null

  return (
    <Card>
      <CardContent className="p-4 space-y-3">
        {/* Label */}
        <label htmlFor="customer-search" className="text-sm font-medium text-muted-foreground">
          Customer {required && <span className="text-destructive">*</span>}
        </label>

        {/* Search input with dropdown */}
        <div ref={dropdownRef} className="relative">
          <Input
            id="customer-search"
            ref={inputRef}
            type="search"
            placeholder="Search customers..."
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setIsOpen(true)
              setHighlightIndex(-1)
            }}
            onFocus={() => {
              if (results.length > 0) setIsOpen(true)
            }}
            onKeyDown={handleKeyDown}
            className="w-full"
          />

          {/* Dropdown */}
          {isOpen && results.length > 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg max-h-64 overflow-y-auto">
              {/* Loading indicator */}
              {isLoading && (
                <div className="px-3 py-2 text-sm text-muted-foreground">Searching...</div>
              )}

              {/* Results list */}
              {!isLoading && results.map((customer, index) => (
                <button
                  key={customer.id}
                  type="button"
                  onClick={() => handleSelectCustomer(customer.id)}
                  onMouseEnter={() => setHighlightIndex(index)}
                  className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                    index === highlightIndex
                      ? 'bg-accent text-accent-foreground'
                      : customerId === customer.id
                        ? 'bg-muted/50 font-medium'
                        : 'hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <div className="font-medium truncate">{customer.displayName}</div>
                  <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
                    {customer.email && (
                      <span className="truncate">{customer.email}</span>
                    )}
                    {customer.phone && (
                      <span className="truncate">{customer.phone}</span>
                    )}
                  </div>
                </button>
              ))}

              {/* No results within the loaded set */}
              {!isLoading && results.length === 0 && query.trim() !== '' && (
                <div className="px-3 py-2 text-sm text-muted-foreground">No customers found</div>
              )}
            </div>
          )}

          {/* Empty state hint — shown when input is focused but no results */}
          {isOpen && query.trim() !== '' && !isLoading && results.length === 0 && (
            <div className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg px-3 py-2 text-sm text-muted-foreground">
              No customers found
            </div>
          )}
        </div>

        {/* Walk-in option — always visible */}
        <button
          type="button"
          onClick={() => handleSelectCustomer(null)}
          className={`w-full justify-start text-sm px-3 py-2 rounded-md border transition-colors ${
            customerId === null
              ? 'bg-primary text-primary-foreground border-transparent'
              : 'border-dashed border-input hover:bg-accent hover:text-accent-foreground'
          }`}
        >
          Walk-in (anonymous) {required && customerId === null && <span className="text-xs opacity-75">(no customer)</span>}
        </button>

        {/* Selected customer info */}
        {customerId !== null && displaySelectedCustomer && (
          <div className="pt-2 border-t text-xs text-muted-foreground space-y-0.5">
            <span className="font-medium">{displaySelectedCustomer.displayName}</span>
            {displaySelectedCustomer.email && <div>{displaySelectedCustomer.email}</div>}
            {displaySelectedCustomer.phone && <div>{displaySelectedCustomer.phone}</div>}
          </div>
        )}

        {/* Walk-in selected info */}
        {customerId === null && (
          <div className="pt-2 border-t text-xs text-muted-foreground italic">
            Anonymous sale — no customer attached
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * Create Order Form — Dialog for creating a new customer order with optional deposit.
 *
 * Uses the shared `CustomerSelector` (see `features/customers/components/CustomerSelector`).
 */

import { useEffect, useState } from 'react'
import { Plus, Trash2 } from 'lucide-react'
import type { CreateOrderFormData, OrderLineItemForm } from '../types.js'
import { createEmptyOrderForm } from '../types.js'
import { createOrder } from '../api.js'
import { formatCentsToEuro } from '@/shared/lib/utils'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Label } from '@/components/ui/label'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CreateOrderDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (orderId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Line Item Row (editable)
// ---------------------------------------------------------------------------

function LineItemRow({ item, onUpdate, onRemove }: {
  item: OrderLineItemForm
  onUpdate: (updates: Partial<OrderLineItemForm>) => void
  onRemove: () => void
}) {
  const lineTypeLabels = ['part', 'labor', 'bicycle'] as const

  return (
    <div className="flex flex-col gap-1.5 p-3 border rounded-md bg-muted/20">
      {/* Line type selector */}
      <select value={item.lineType} onChange={(e) => onUpdate({ lineType: e.target.value as OrderLineItemForm['lineType'] })}
        className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none w-fit">
        {lineTypeLabels.map(t => <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>)}
      </select>

      {/* Description */}
      <input type="text" value={item.description} onChange={(e) => onUpdate({ description: e.target.value })} placeholder="Description"
        className="flex-1 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none min-w-[150px]" />

      {/* Bicycle ID — shown only for bicycle line items */}
      {item.lineType === 'bicycle' && (
        <input type="text" value={item.bicycleId ?? ''} onChange={(e) => onUpdate({ bicycleId: e.target.value || null })} placeholder="Bicycle ID"
          className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none w-full font-mono" />
      )}

      <div className="flex items-center gap-2">
        {/* Quantity */}
        <input type="number" value={item.quantity} onChange={(e) => onUpdate({ quantity: Math.max(1, parseInt(e.target.value) || 1) })} min={1}
          className="w-16 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none text-right" />

        {/* Unit Price (cents) */}
        <input type="number" value={item.unitPriceNet} onChange={(e) => onUpdate({ unitPriceNet: Math.max(0, parseInt(e.target.value) || 0) })} min={0} placeholder="Cents"
          className="w-24 h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none text-right font-mono" />

        {/* VAT Rate */}
        <select value={item.vatRateId} onChange={(e) => onUpdate({ vatRateId: e.target.value })}
          className="h-8 px-2 text-xs rounded border border-input bg-background focus:border-ring focus:outline-none">
          <option value="">VAT…</option>
        </select>

        {/* Remove button */}
        <Button variant="ghost" size="sm" onClick={onRemove} className="h-8 w-8 p-0 text-red-500 hover:text-red-700 hover:bg-red-50">
          <Trash2 className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

// ---------------------------------------------------------------------------
// Component — Create Order Dialog
// ---------------------------------------------------------------------------

export function CreateOrderFormDialog({ isOpen, onClose, onSuccess }: CreateOrderDialogProps) {
  const [formData, setFormData] = useState<CreateOrderFormData>(createEmptyOrderForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  // Track whether any bicycle line item references a leased bicycle
  const [hasLeasedBicycle, setHasLeasedBicycle] = useState(false)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyOrderForm())
      setError(null)
      setHasLeasedBicycle(false)
    }
  }, [isOpen])

  // Check lease status for bicycle line items — fetches each bicycle ID from API
  useEffect(() => {
    const bicycleIds = formData.lineItems
      .filter(item => item.lineType === 'bicycle' && item.bicycleId)
      .map(item => item.bicycleId!)

    if (bicycleIds.length === 0) {
      setHasLeasedBicycle(false)
      return
    }

    let cancelled = false
    async function checkLeases() {
      for (const id of bicycleIds) {
        try {
          const res = await fetch(`/api/bicycles/${id}`)
          if (res.ok && !cancelled) {
            const data = await res.json()
            if (data.bicycle?.isLease === true) {
              setHasLeasedBicycle(true)
              return
            }
          }
        } catch { /* Silently fail — server-side validation is the source of truth */ }
      }
      if (!cancelled) setHasLeasedBicycle(false)
    }
    checkLeases()
    return () => { cancelled = true }
  }, [formData.lineItems])

  // Deposit amount tracking — disabled when leased bicycles present
  const depositAmount = formData.depositAmount ?? null
  const hasDeposit = depositAmount != null && depositAmount > 0
  const showPaymentMethod = hasDeposit && !hasLeasedBicycle

  // Add a new line item row
  const addLineItem = () => {
    setFormData(prev => ({
      ...prev,
      lineItems: [...prev.lineItems, {
        lineType: 'part',
        description: '',
        quantity: 1,
        unitPriceNet: 0,
        vatRateId: '',
      }],
    }))
  }

  // Update a specific line item
  const updateLineItem = (index: number, updates: Partial<OrderLineItemForm>) => {
    setFormData(prev => ({
      ...prev,
      lineItems: prev.lineItems.map((item, i) => i === index ? { ...item, ...updates } : item),
    }))
  }

  // Remove a line item
  const removeLineItem = (index: number) => {
    setFormData(prev => ({
      ...prev,
      lineItems: prev.lineItems.filter((_, i) => i !== index),
    }))
  }

  // Compute total net from line items
  const totalNet = formData.lineItems.reduce((sum, item) => sum + (item.unitPriceNet * item.quantity), 0)

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      // Validate required fields
      if (!formData.customerId) throw new Error('Customer is required')
      if (formData.lineItems.length === 0) throw new Error('At least one line item is required')
      for (const item of formData.lineItems) {
        if (!item.description.trim()) throw new Error('All line items must have a description')
        if (item.unitPriceNet <= 0) throw new Error('Unit price must be greater than 0')
      }
      // Reject deposit when leased bicycles present
      if (hasLeasedBicycle && hasDeposit) {
        throw new Error('Deposit not allowed for orders containing leased bicycles')
      }

      const orderInput = {
        customerId: formData.customerId,
        lineItems: formData.lineItems.map(item => ({
          lineType: item.lineType,
          partId: item.partId ?? null,
          laborServiceId: item.laborServiceId ?? null,
          description: item.description,
          quantity: item.quantity,
          unitPriceNet: item.unitPriceNet,
          vatRateId: item.vatRateId,
          discountPercent: item.discountPercent ?? null,
          bicycleId: item.bicycleId ?? null,
          bicycleBrand: item.bicycleBrand ?? null,
          bicycleModel: item.bicycleModel ?? null,
          bicycleYear: item.bicycleYear ?? null,
          bicycleColor: item.bicycleColor ?? null,
          bicycleFrameSize: item.bicycleFrameSize ?? null,
        })),
        depositAmount: (depositAmount != null && depositAmount > 0) ? depositAmount : undefined,
        paymentMethod: showPaymentMethod ? formData.paymentMethod : undefined,
      }

      const result = await createOrder(orderInput)
      onSuccess(result.order.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create order')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>New Customer Order</DialogTitle>
          <DialogDescription>
            Create a customer order for parts or bicycles not in stock. Optionally collect a deposit upfront.
          </DialogDescription>
        </DialogHeader>

        {error && (
          <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Customer Selector — shared component, required for orders */}
          <CustomerSelector
            customerId={formData.customerId}
            onSelect={(customerId) => setFormData(prev => ({ ...prev, customerId }))}
            required
          />

          {/* Line Items */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label className="text-sm font-medium text-muted-foreground">Line Items</Label>
              <Button type="button" variant="outline" size="sm" onClick={addLineItem} className="h-7 px-2 text-xs gap-1">
                <Plus className="h-3 w-3" /> Add Item
              </Button>
            </div>

            {formData.lineItems.length === 0 ? (
              <div className="text-center py-6 border rounded-md border-dashed text-sm text-muted-foreground">
                No line items yet. Click "Add Item" to start.
              </div>
            ) : (
              <div className="space-y-2">
                {formData.lineItems.map((item, index) => (
                  <LineItemRow key={index} item={item} onUpdate={(updates) => updateLineItem(index, updates)} onRemove={() => removeLineItem(index)} />
                ))}

                {/* Total */}
                <div className="flex justify-end pt-2 border-t text-sm">
                  <span className="text-muted-foreground mr-auto">Total (net):</span>
                  <span className="font-mono font-medium">{formatCentsToEuro(totalNet)}</span>
                </div>
              </div>
            )}
          </div>

          {/* Deposit Section */}
          <div className="space-y-3 border-t pt-4">
            <Label className="text-sm font-medium text-muted-foreground">Deposit (optional)</Label>

            {hasLeasedBicycle && (
              <div className="p-2 bg-yellow-50 border border-yellow-200 rounded text-xs text-yellow-800 dark:bg-yellow-900/20 dark:border-yellow-700 dark:text-yellow-400">
                ⚠️ Deposit not allowed — order contains a leased bicycle
              </div>
            )}

            <div className="flex items-center gap-3">
              <input type="number" value={depositAmount ?? ''} onChange={(e) => {
                if (hasLeasedBicycle) return
                const val = e.target.value === '' ? null : Math.max(0, parseInt(e.target.value) || 0)
                setFormData(prev => ({ ...prev, depositAmount: val }))
              }} min={0} placeholder="0" disabled={hasLeasedBicycle}
                className={`w-32 h-9 px-3 text-sm rounded border font-mono focus:border-ring focus:outline-none ${hasLeasedBicycle ? 'opacity-50 cursor-not-allowed bg-muted' : ''}`} />
              <span className="text-xs text-muted-foreground">cents</span>
            </div>

            {/* Payment Method (only shown when deposit > 0) */}
            {showPaymentMethod && (
              <div className="space-y-2 pt-2 border-t">
                <Label className="text-sm font-medium text-muted-foreground">Deposit Payment Method</Label>
                <div className="grid grid-cols-3 gap-2">
                  {(['cash', 'card', 'bank_transfer'] as const).map((method) => (
                    <Button key={method} type="button" variant={formData.paymentMethod === method ? 'default' : 'outline'} size="sm"
                      onClick={() => setFormData(prev => ({ ...prev, paymentMethod: method }))}>
                      {method === 'cash' ? '💵 Cash' : method === 'card' ? '💳 Card' : '🏦 Transfer'}
                    </Button>
                  ))}
                </div>

                {/* Deposit summary */}
                <div className="mt-2 p-3 bg-accent rounded-md text-sm">
                  <div className="flex justify-between mb-1">
                    <span className="text-muted-foreground">Deposit:</span>
                    <span className="font-mono font-medium">{formatCentsToEuro(depositAmount!)}</span>
                  </div>
                  <div className="flex justify-between text-xs text-muted-foreground">
                    <span>Balance due at pickup:</span>
                    <span className="font-mono">{formatCentsToEuro(Math.max(0, totalNet - depositAmount!))}</span>
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Actions */}
          <DialogFooter className="gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} disabled={submitting}>
              Cancel
            </Button>
            <Button type="submit" disabled={submitting || !formData.customerId || formData.lineItems.length === 0}>
              {submitting ? 'Creating...' : 'Create Order'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

/**
 * RepairIntakeModal — Single-form modal for creating new repairs.
 *
 * Collects customer (search existing or create inline), bicycle (select from
 * customer's bikes or create inline with brand/model/color), and notes, then
 * submits atomically via POST /api/repairs.
 *
 * Features:
 * - Single-form layout (not multi-step wizard)
 * - Customer search/select via shared `CustomerSelector` OR inline creation
 * - Bicycle selection from customer's existing bikes or inline creation
 * - Customer-facing notes field
 * - Client-side validation before submission
 *
 * CUSTOM COMBOBOX PATTERN:
 * Customer selection now uses the shared `CustomerSelector` component
 * (see `features/customers/components/CustomerSelector`). The bicycle
 * combobox remains a local custom dropdown (Radix Select failed inside
 * Dialog.Portal due to nested Portal conflicts — same proven pattern as
 * before).
 */

import { useEffect, useRef, useState } from 'react'
import * as DialogPrimitive from '@radix-ui/react-dialog'
import { Check, X } from 'lucide-react'
import toast from 'react-hot-toast'
import { cn } from '@/shared/lib/utils.js'
import { Button } from '@/components/ui/button.js'
import { Input } from '@/components/ui/input.js'
import { Label } from '@/components/ui/label.js'
import { Textarea } from '@/components/ui/textarea.js'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import { createRepair, getCustomerWithBicycles } from '../api.js'
import type {
  RepairIntakeFormData,
  IntakeBicycle,
} from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

/** Default empty form state */
const EMPTY_FORM: RepairIntakeFormData = {
  customerMode: 'existing',
  newPhone: '',
  newEmail: '',
  bicycleMode: 'select_existing',
  newBrand: '',
  newModel: '',
  newColor: '',
  customerNotes: '',
  plannedDate: undefined,
  pickupDate: undefined,
}

// ---------------------------------------------------------------------------
// Props
// ---------------------------------------------------------------------------

interface RepairIntakeModalProps {
  /** Open state controlled by parent */
  open: boolean
  /** Callback when modal opens/closes */
  onOpenChange: (open: boolean) => void
  /** Callback after successful repair creation */
  onSuccess: () => void
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export function RepairIntakeModal({ open, onOpenChange, onSuccess }: RepairIntakeModalProps) {
  // Form state
  const [form, setForm] = useState<RepairIntakeFormData>(EMPTY_FORM)
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Customer's bicycles (loaded after a customer is selected)
  const [customerBicycles, setCustomerBicycles] = useState<IntakeBicycle[]>([])

  // Validation errors
  const [errors, setErrors] = useState<Record<string, string>>({})

  // ── Bicycle dropdown state (custom combobox — replaces Radix Select) ────

  const bicycleDropdownRef = useRef<HTMLDivElement>(null)
  const [bicycleIsOpen, setBicycleIsOpen] = useState(false)
  const [bicycleHighlightIndex, setBicycleHighlightIndex] = useState(-1)

  // ---------------------------------------------------------------------------
  // Effects — reset form when modal opens
  // ---------------------------------------------------------------------------

  useEffect(() => {
    if (open) {
      resetForm()
    }
  }, [open])

  // Load bicycles when a customer is selected or mode changes to existing
  useEffect(() => {
    if (form.customerMode === 'existing' && form.existingCustomerId) {
      loadCustomerBicycles(form.existingCustomerId)
    } else {
      setCustomerBicycles([])
    }
  }, [form.customerMode, form.existingCustomerId])

  // ── Click-outside handler — close bicycle dropdown when clicking outside ─

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      const target = event.target as Node

      // Close bicycle dropdown if click is outside both the input and dropdown
      if (
        bicycleDropdownRef.current &&
        !bicycleDropdownRef.current.contains(target)
      ) {
        setBicycleIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ---------------------------------------------------------------------------
  // Data loading
  // ---------------------------------------------------------------------------

  async function loadCustomerBicycles(customerId: string) {
    try {
      const data = await getCustomerWithBicycles(customerId)
      setCustomerBicycles(data.bicycles || [])
    } catch {
      setCustomerBicycles([])
    }
  }

  // ---------------------------------------------------------------------------
  // Form helpers
  // ---------------------------------------------------------------------------

  function resetForm() {
    setForm(EMPTY_FORM)
    setCustomerBicycles([])
    setErrors({})
    setBicycleIsOpen(false)
  }

  function updateField<K extends keyof RepairIntakeFormData>(field: K, value: RepairIntakeFormData[K]) {
    setForm(prev => ({ ...prev, [field]: value }))
    // Clear error for this field when user starts typing
    if (errors[field]) {
      setErrors(prev => {
        const next = { ...prev }
        delete next[field]
        return next
      })
    }
  }

  function handleCustomerModeChange(mode: 'existing' | 'new') {
    updateField('customerMode', mode)
    if (mode === 'new') {
      setForm(prev => ({ ...prev, existingCustomerId: undefined }))
      setCustomerBicycles([])
    } else {
      // Reset inline customer fields when switching back to existing
      updateField('newFirstName', undefined)
      updateField('newLastName', undefined)
      updateField('newCompanyName', undefined)
    }
  }

  function handleBicycleModeChange(mode: 'select_existing' | 'create_new') {
    updateField('bicycleMode', mode)
    if (mode === 'create_new') {
      setForm(prev => ({ ...prev, existingBicycleId: undefined }))
    } else {
      // Reset inline bicycle fields when switching back to select
      updateField('newBrand', '')
      updateField('newModel', '')
      updateField('newColor', '')
    }
  }

  // ── Bicycle dropdown handlers (custom combobox) ─────────────────────────

  function handleSelectBicycle(bicycleId: string) {
    updateField('existingBicycleId', bicycleId)
    setBicycleIsOpen(false)
  }

  function handleBicycleKeyDown(e: React.KeyboardEvent<HTMLInputElement>) {
    if (!bicycleIsOpen || customerBicycles.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setBicycleHighlightIndex(prev => Math.min(prev + 1, customerBicycles.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setBicycleHighlightIndex(prev => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (bicycleHighlightIndex >= 0 && bicycleHighlightIndex < customerBicycles.length) {
          handleSelectBicycle(customerBicycles[bicycleHighlightIndex].id)
        } else if (customerBicycles.length === 1) {
          // Auto-select single result
          handleSelectBicycle(customerBicycles[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setBicycleIsOpen(false)
        break
    }
  }

  // ---------------------------------------------------------------------------
  // Validation
  // ---------------------------------------------------------------------------

  function validateForm(): boolean {
    const newErrors: Record<string, string> = {}

    // Customer validation
    if (form.customerMode === 'new') {
      if (!form.newPhone || form.newPhone.trim().length < 1) {
        newErrors.newPhone = 'Phone is required'
      }
    } else {
      if (!form.existingCustomerId) {
        newErrors.existingCustomerId = 'Please select a customer'
      }
    }

    // Bicycle validation
    if (form.bicycleMode === 'create_new') {
      if (!form.newBrand || form.newBrand.trim().length < 1) {
        newErrors.newBrand = 'Brand is required'
      }
      if (!form.newModel || form.newModel.trim().length < 1) {
        newErrors.newModel = 'Model is required'
      }
      if (!form.newColor || form.newColor.trim().length < 1) {
        newErrors.newColor = 'Color is required'
      }
    } else {
      if (!form.existingBicycleId) {
        newErrors.existingBicycleId = 'Please select a bicycle'
      }
    }

    // Notes validation
    if (!form.customerNotes || form.customerNotes.trim().length < 1) {
      newErrors.customerNotes = 'Customer notes are required'
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  // ---------------------------------------------------------------------------
  // Submission
  // ---------------------------------------------------------------------------

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()

    if (!validateForm()) return

    setIsSubmitting(true)

    try {
      const input = buildIntakeInput()
      await createRepair(input)
      toast.success('Repair created successfully')
      onOpenChange(false)
      onSuccess()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create repair'
      toast.error(message)
    } finally {
      setIsSubmitting(false)
    }
  }

  function buildIntakeInput(): Parameters<typeof createRepair>[0] {
    const base = {
      bicycleMode: form.bicycleMode,
      existingBicycleId: form.existingBicycleId,
      newBicycle: form.bicycleMode === 'create_new' ? {
        brand: form.newBrand,
        model: form.newModel,
        color: form.newColor || '',
      } : undefined,
      customerNotes: form.customerNotes,
    }

    if (form.customerMode === 'new') {
      return {
        ...base,
        customerMode: 'new',
        newCustomer: {
          firstName: form.newFirstName,
          lastName: form.newLastName,
          companyName: form.newCompanyName,
          phone: form.newPhone,
          email: form.newEmail || undefined,
        },
      }
    }

    return {
      ...base,
      customerMode: 'existing',
      existingCustomerId: form.existingCustomerId!,
    }
  }

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------

  return (
    <DialogPrimitive.Root open={open} onOpenChange={(isOpen) => {
      if (!isOpen) resetForm()
      onOpenChange(isOpen)
    }}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay className="fixed inset-0 z-50 bg-black/80 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0" />
        <DialogPrimitive.Content
          className={cn(
            'fixed left-[50%] top-[50%] z-50 w-full max-w-xl translate-x-[-50%] translate-y-[-50%] gap-4 border bg-background p-6 shadow-lg duration-200 data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[state=closed]:slide-out-to-left-1/2 data-[state=closed]:slide-out-to-top-[48%] data-[state=open]:slide-in-from-left-1/2 data-[state=open]:slide-in-from-top-[48%] sm:rounded-lg',
            'max-h-[90vh] overflow-y-auto'
          )}
        >
          {/* Header */}
          <div className="flex items-center justify-between mb-4">
            <DialogPrimitive.Title className="text-lg font-semibold leading-none tracking-tight text-foreground">
              New Repair Intake
            </DialogPrimitive.Title>
            <DialogPrimitive.Close asChild>
              <Button variant="ghost" size="sm" className="h-6 w-6 p-0 !bg-transparent hover:!bg-accent">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </Button>
            </DialogPrimitive.Close>
          </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-5">
          {/* Customer Section */}
          <fieldset className="rounded-lg p-4 space-y-3 border border-border bg-muted/50">
            <legend className="text-sm font-semibold text-foreground px-2">Customer</legend>

            {/* Mode toggle */}
            <div className="flex gap-2">
              <Button
                type="button"
                variant={form.customerMode === 'existing' ? 'default' : 'outline'}
                size="sm"
                onClick={() => handleCustomerModeChange('existing')}
                className={cn(
                  form.customerMode === 'existing' && '!bg-[hsl(var(--primary))] !text-[hsl(var(--primary-foreground))] hover:!bg-[hsl(var(--primary))/90]'
                )}
              >
                Select Existing
              </Button>
              <Button
                type="button"
                variant={form.customerMode === 'new' ? 'default' : 'outline'}
                size="sm"
                onClick={() => handleCustomerModeChange('new')}
                className={cn(
                  form.customerMode === 'new' && '!bg-[hsl(var(--primary))] !text-[hsl(var(--primary-foreground))] hover:!bg-[hsl(var(--primary))/90]'
                )}
              >
                New Customer (Walk-in)
              </Button>
            </div>

            {form.customerMode === 'existing' ? (
              /* Existing customer select — SHARED CustomerSelector component */
              <div className="space-y-1">
                <Label htmlFor="customer-search" className="text-xs font-medium text-muted-foreground">Search or select a customer</Label>
                <CustomerSelector
                  customerId={form.existingCustomerId ?? null}
                  onSelect={(customerId) => updateField('existingCustomerId', customerId ?? undefined)}
                  required
                />

                {errors.existingCustomerId && (
                  <p className="text-xs text-destructive">{errors.existingCustomerId}</p>
                )}

                {/* Show customer's bicycles count if a customer is selected */}
                {form.existingCustomerId && customerBicycles.length > 0 && (
                  <div className="mt-2">
                    <p className="text-xs font-medium text-muted-foreground">This customer has {customerBicycles.length} bicycle(s)</p>
                  </div>
                )}
              </div>
            ) : (
              /* Inline new customer creation */
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1">
                  <Label htmlFor="new-firstName" className="text-xs font-medium text-muted-foreground">First Name</Label>
                  <Input
                    id="new-firstName"
                    value={form.newFirstName ?? ''}
                    onChange={(e) => updateField('newFirstName', e.target.value || undefined)}
                    placeholder="Jane"
                    className="h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground"
                  />
                </div>
                <div className="space-y-1">
                  <Label htmlFor="new-lastName" className="text-xs font-medium text-muted-foreground">Last Name</Label>
                  <Input
                    id="new-lastName"
                    value={form.newLastName ?? ''}
                    onChange={(e) => updateField('newLastName', e.target.value || undefined)}
                    placeholder="Doe"
                    className="h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground"
                  />
                </div>
                <div className="space-y-1">
                  <Label htmlFor="new-phone" className="text-xs font-medium text-muted-foreground">Phone *</Label>
                  <Input
                    id="new-phone"
                    value={form.newPhone}
                    onChange={(e) => updateField('newPhone', e.target.value)}
                    placeholder="+32 470 123 456"
                    className={cn('h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground', errors.newPhone && 'border-destructive focus-visible:ring-destructive')}
                  />
                  {errors.newPhone && <p className="text-xs text-destructive">{errors.newPhone}</p>}
                </div>
                <div className="space-y-1">
                  <Label htmlFor="new-email" className="text-xs font-medium text-muted-foreground">Email</Label>
                  <Input
                    id="new-email"
                    type="email"
                    value={form.newEmail}
                    onChange={(e) => updateField('newEmail', e.target.value)}
                    placeholder="jane@example.com"
                    className="h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground"
                  />
                </div>
              </div>
            )}
          </fieldset>

          {/* Bicycle Section */}
          <fieldset className="rounded-lg p-4 space-y-3 border border-border bg-muted/50">
            <legend className="text-sm font-semibold text-foreground px-2">Bicycle</legend>

            {/* Mode toggle */}
            <div className="flex gap-2">
              <Button
                type="button"
                variant={form.bicycleMode === 'select_existing' ? 'default' : 'outline'}
                size="sm"
                onClick={() => handleBicycleModeChange('select_existing')}
                className={cn(
                  form.bicycleMode === 'select_existing' && '!bg-[hsl(var(--primary))] !text-[hsl(var(--primary-foreground))] hover:!bg-[hsl(var(--primary))/90]'
                )}
              >
                Select Existing
              </Button>
              <Button
                type="button"
                variant={form.bicycleMode === 'create_new' ? 'default' : 'outline'}
                size="sm"
                onClick={() => handleBicycleModeChange('create_new')}
                className={cn(
                  form.bicycleMode === 'create_new' && '!bg-[hsl(var(--primary))] !text-[hsl(var(--primary-foreground))] hover:!bg-[hsl(var(--primary))/90]'
                )}
              >
                New Bicycle
              </Button>
            </div>

            {form.bicycleMode === 'select_existing' ? (
              /* Existing bicycle select — CUSTOM COMBOBOX (no Radix Select) */
              <div className="space-y-1">
                {customerBicycles.length > 0 ? (
                  <>
                    {/* Bicycle combobox container */}
                    <div ref={bicycleDropdownRef} className="relative">
                      <Input
                        id="bicycle-search"
                        type="search"
                        role="combobox"
                        aria-expanded={bicycleIsOpen}
                        aria-controls="bicycle-dropdown-listbox"
                        aria-autocomplete="list"
                        aria-label="Select a bicycle"
                        placeholder="Select a bicycle..."
                        value={form.existingBicycleId
                          ? (() => {
                              const bike = customerBicycles.find(b => b.id === form.existingBicycleId)
                              return bike ? `${bike.brand} ${bike.model}${bike.color ? ` — ${bike.color}` : ''}` : 'Select a bicycle...'
                            })()
                          : 'Select a bicycle...'}
                        onFocus={() => setBicycleIsOpen(true)}
                        onClick={() => {
                          setBicycleIsOpen(true)
                          setBicycleHighlightIndex(-1)
                        }}
                        onKeyDown={handleBicycleKeyDown}
                        className="w-full"
                      />

                      {/* Bicycle dropdown — absolute positioned, no portal */}
                      {bicycleIsOpen && (
                        <div
                          id="bicycle-dropdown-listbox"
                          role="listbox"
                          className="absolute z-50 w-full mt-1 bg-popover border rounded-md shadow-lg max-h-48 overflow-y-auto"
                        >
                          {customerBicycles.map((bicycle, index) => (
                            <button
                              key={bicycle.id}
                              type="button"
                              role="option"
                              aria-selected={form.existingBicycleId === bicycle.id}
                              onClick={() => handleSelectBicycle(bicycle.id)}
                              onMouseEnter={() => setBicycleHighlightIndex(index)}
                              className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                                index === bicycleHighlightIndex
                                  ? 'bg-accent text-accent-foreground'
                                  : 'hover:bg-accent hover:text-accent-foreground'
                              }`}
                            >
                              {bicycle.brand} {bicycle.model}{bicycle.color ? ` — ${bicycle.color}` : ''}
                            </button>
                          ))}

                          {/* Selected indicator */}
                          {bicycleHighlightIndex >= 0 && bicycleHighlightIndex < customerBicycles.length && (
                            <div className="absolute right-2 top-1/2 -translate-y-1/2">
                              <Check className="h-4 w-4" />
                            </div>
                          )}
                        </div>
                      )}
                    </div>

                    {errors.existingBicycleId && (
                      <p className="text-xs text-destructive">{errors.existingBicycleId}</p>
                    )}
                  </>
                ) : (
                  <div className="rounded-md border-2 border-dashed border-border bg-muted p-4 text-center">
                    <p className="text-sm font-medium text-foreground">
                      {form.existingCustomerId ? 'This customer has no bicycles yet' : 'Select a customer first to see their bicycles'}
                    </p>
                    <Button
                      type="button"
                      variant="link"
                      size="sm"
                      className="mt-1 h-auto p-0 text-xs"
                      onClick={() => handleBicycleModeChange('create_new')}
                    >
                      Create a new bicycle instead →
                    </Button>
                  </div>
                )}
              </div>
            ) : (
              /* Inline new bicycle creation */
              <div className="grid grid-cols-3 gap-3">
                <div className="space-y-1">
                  <Label htmlFor="new-brand" className="text-xs font-medium text-muted-foreground">Brand *</Label>
                  <Input
                    id="new-brand"
                    value={form.newBrand}
                    onChange={(e) => updateField('newBrand', e.target.value)}
                    placeholder="Trek"
                    className={cn('h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground', errors.newBrand && 'border-destructive focus-visible:ring-destructive')}
                  />
                  {errors.newBrand && <p className="text-xs font-medium text-destructive">{errors.newBrand}</p>}
                </div>
                <div className="space-y-1">
                  <Label htmlFor="new-model" className="text-xs font-medium text-muted-foreground">Model *</Label>
                  <Input
                    id="new-model"
                    value={form.newModel}
                    onChange={(e) => updateField('newModel', e.target.value)}
                    placeholder="Fuel EX"
                    className={cn('h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground', errors.newModel && 'border-destructive focus-visible:ring-destructive')}
                  />
                  {errors.newModel && <p className="text-xs text-destructive">{errors.newModel}</p>}
                </div>
                <div className="space-y-1">
                  <Label htmlFor="new-color" className="text-xs font-medium text-muted-foreground">Color *</Label>
                  <Input
                    id="new-color"
                    value={form.newColor}
                    onChange={(e) => updateField('newColor', e.target.value)}
                    placeholder="Green"
                    className={cn('h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground', errors.newColor && 'border-destructive focus-visible:ring-destructive')}
                  />
                  {errors.newColor && <p className="text-xs font-medium text-destructive">{errors.newColor}</p>}
                </div>
              </div>
            )}
          </fieldset>

          {/* Customer Notes */}
          <div className="space-y-1">
            <Label htmlFor="customer-notes" className="text-sm font-medium text-foreground">Customer Notes *</Label>
            <Textarea
              id="customer-notes"
              value={form.customerNotes}
              onChange={(e) => updateField('customerNotes', e.target.value)}
              placeholder="Describe the issue, customer complaints, or intake observations..."
              rows={3}
              className={cn('text-sm resize-none border-input focus:border-primary placeholder:text-muted-foreground', errors.customerNotes && 'border-destructive focus-visible:ring-destructive')}
            />
            {errors.customerNotes && (
              <p className="text-xs text-destructive">{errors.customerNotes}</p>
            )}
          </div>

          {/* Optional Scheduling Dates */}
          <fieldset className="rounded-lg p-4 space-y-3 border border-border bg-muted/50">
            <legend className="text-sm font-semibold text-foreground px-2">Scheduling (optional)</legend>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <Label htmlFor="planned-date" className="text-xs font-medium text-muted-foreground">Planned Date</Label>
                <Input
                  id="planned-date"
                  type="date"
                  value={form.plannedDate ? new Date(form.plannedDate).toISOString().split('T')[0] : ''}
                  onChange={(e) => updateField('plannedDate', e.target.value ? new Date(e.target.value).getTime() : undefined)}
                  placeholder="Not set"
                  className="h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground"
                />
              </div>
              <div className="space-y-1">
                <Label htmlFor="pickup-date" className="text-xs font-medium text-muted-foreground">Pickup Date</Label>
                <Input
                  id="pickup-date"
                  type="date"
                  value={form.pickupDate ? new Date(form.pickupDate).toISOString().split('T')[0] : ''}
                  onChange={(e) => updateField('pickupDate', e.target.value ? new Date(e.target.value).getTime() : undefined)}
                  placeholder="Not set"
                  className="h-9 text-sm border-input focus:border-primary placeholder:text-muted-foreground"
                />
              </div>
            </div>
          </fieldset>

          {/* Actions */}
          <div className="pt-4 mt-4 border-t">
            <div className="flex justify-end gap-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => { onOpenChange(false); resetForm() }}
                disabled={isSubmitting}
                className="!border-border !text-foreground hover:!bg-accent"
              >
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting} className="!bg-[hsl(var(--primary))] !text-[hsl(var(--primary-foreground))] hover:!bg-[hsl(var(--primary))/90]">
                {isSubmitting ? 'Creating...' : 'Create Repair'}
              </Button>
            </div>
          </div>
        </form>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

/**
 * Create Quote Form — Dialog for creating a new draft quote.
 *
 * Uses the shared `CustomerSelector` (see `features/customers/components/CustomerSelector`).
 * Quotes allow anonymous (walk-in) customers — `required` is NOT passed.
 */

import { useEffect, useState } from 'react'
import type { CreateQuoteFormData } from '../types.js'
import { createEmptyQuoteForm } from '../types.js'
import { createQuote } from '../api.js'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface CreateQuoteDialogProps {
  isOpen: boolean
  onClose: () => void
  onSuccess: (quoteId: string) => void
}

// ---------------------------------------------------------------------------
// Component — Create Quote Dialog
// ---------------------------------------------------------------------------

export function CreateQuoteDialog({ isOpen, onClose, onSuccess }: CreateQuoteDialogProps) {
  const [formData, setFormData] = useState<CreateQuoteFormData>(createEmptyQuoteForm())
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Reset form when dialog opens
  useEffect(() => {
    if (isOpen) {
      setFormData(createEmptyQuoteForm())
      setError(null)
    }
  }, [isOpen])

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmitting(true)
    setError(null)

    try {
      const quote = await createQuote(formData)
      onSuccess(quote.id)
      onClose()
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create quote')
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>New Quote</DialogTitle>
          <DialogDescription>
            Create a new draft quote. You can add line items after creation.
          </DialogDescription>
        </DialogHeader>

        {error && (
          <div className="rounded-md border border-red-200 bg-red-50 p-3 text-sm text-red-700 dark:bg-red-900/20 dark:border-red-800 dark:text-red-400">
            {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Customer Selector — shared component, walk-in allowed (no `required`) */}
          <CustomerSelector
