/**
 * POS feature API — typed client functions for all POS endpoints.
 *
 * Uses explicit types from `types.ts` and shared domain types from `shared/types/`.
 */

import type { CheckoutPayload, CheckoutSuccess, CustomerSelectorItem } from './types.js'

// ============================================================================
// Types — Server response shapes (raw JSON from Hono routes)
// ============================================================================

/** Response shape for a created sale. */
export interface SaleResponse {
  /** The created sale header. */
  sale: Record<string, unknown>
  /** The payment record for this sale. */
  payment: Record<string, unknown>
  /** All line items for this sale. */
  lineItems: Record<string, unknown>[]
}

/** Error response from POST /sales. */
export interface SaleError {
  error: string
  code?: string
  shortfalls?: Array<{ partId: string; requested: number; available: number }>
}

/** Response envelope for the customer list endpoint. */
export interface CustomerListResponse {
  customers: CustomerSelectorItem[]
}

// ============================================================================
// API Base URL — empty string means same-origin (Vite proxy handles /api).
// ============================================================================

const API_BASE = ''

// ============================================================================
// Checkout API — POST /sales
// ============================================================================

/**
 * Submit a checkout to the server.
 *
 * Calls `POST /api/sales` with the cart payload and returns the created sale
 * data, or throws on failure.
 *
 * @param payload — Checkout payload from cart store
 * @returns Sale response with sale header, payment, and line items
 */
export async function submitCheckout(payload: CheckoutPayload): Promise<SaleResponse> {
  const response = await fetch(`${API_BASE}/api/sales`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  })

  if (!response.ok) {
    const errorBody = (await response.json().catch(() => ({}))) as SaleError
    throw new Error(errorBody.error ?? `Checkout failed with status ${response.status}`)
  }

  return (await response.json()) as SaleResponse
}

/**
 * Extract sale number and total from a successful checkout response.
 */
export function parseCheckoutSuccess(response: SaleResponse): CheckoutSuccess {
  const sale = response.sale as Record<string, unknown>
  return {
    saleNumber: String(sale.sale_number ?? ''),
    totalGross: Number(sale.total_gross ?? 0),
  }
}

// ============================================================================
// Customer API — GET /customers
// ============================================================================

/**
 * Fetch all customers formatted as a compact list suitable for dropdown selectors.
 *
 * @returns Customer selector items sorted by display name
 */
export async function getCustomerList(): Promise<CustomerSelectorItem[]> {
  const response = await fetch(`${API_BASE}/api/customers`)

  if (!response.ok) {
    throw new Error(`Failed to fetch customer list: ${response.status}`)
  }

  const data = (await response.json()) as CustomerListResponse
  return data.customers
}

import { useCallback, useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { useCartStore } from '../store'
import { PartsSearch } from '../components/PartsSearch'
import { CartDisplay } from '../components/CartDisplay'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import { PaymentDialog } from '../components/PaymentDialog'
import { submitCheckout, parseCheckoutSuccess } from '../services/checkout'

// ============================================================================
// Component — POS Page (split-panel layout)
// ============================================================================

export function PosPage() {
  const customerId = useCartStore((s) => s.customerId)
  const setCustomer = useCartStore((s) => s.setCustomer)
  const startCheckout = useCartStore((s) => s.startCheckout)
  const finishCheckout = useCartStore((s) => s.finishCheckout)
  const failCheckout = useCartStore((s) => s.failCheckout)
  const getCheckoutPayload = useCartStore((s) => s.getCheckoutPayload)

  // Handle checkout submission
  const handleCheckout = useCallback(
    async (method: PaymentMethodType) => {
      startCheckout()

      try {
        const payload = getCheckoutPayload()
        // Override payment method from the form selection
        const checkoutPayload = { ...payload, paymentMethod: method }

        const response = await submitCheckout(checkoutPayload)
        const success = parseCheckoutSuccess(response)
        finishCheckout(success)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error during checkout'
        failCheckout(message)
      }
    },
    [startCheckout, finishCheckout, failCheckout, getCheckoutPayload]
  )

  const [paymentOpen, setPaymentOpen] = useState(false)
  const canCheckout = useCartStore((s) => s.canCheckout)

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <CardHeader className="pb-2 px-6 pt-4">
        <CardTitle className="text-xl">Point of Sale</CardTitle>
      </CardHeader>

      {/* Split-panel layout */}
      <div className="flex flex-1 gap-4 px-6 pb-4 overflow-hidden">
        {/* Left panel — Parts search + Cart display */}
        <div className="flex-1 flex flex-col gap-4 min-w-0">
          <Card>
            <CardHeader className="pb-2 px-4 pt-4">
              <CardTitle className="text-base">Add Items</CardTitle>
            </CardHeader>
            <CardContent className="px-4 pb-4">
              <PartsSearch />
            </CardContent>
          </Card>

          <div className="flex-1 min-h-0">
            <CartDisplay />
          </div>
        </div>

        {/* Right panel — Customer selector + Pay button */}
        <div className="w-80 shrink-0 flex flex-col gap-4 overflow-y-auto">
          <CustomerSelector customerId={customerId} onSelect={(id) => setCustomer(id)} />
          <Button
            onClick={() => setPaymentOpen(true)}
            disabled={!canCheckout}
            size="lg"
            className="w-full"
          >
            Pay
          </Button>
        </div>
      </div>

      {/* Payment dialog */}
      <PaymentDialog
        open={paymentOpen}
        onClose={() => setPaymentOpen(false)}
        onCheckout={handleCheckout}
      />
    </div>
  )
}

