import { useCallback, useEffect, useState } from 'react'
import type { SaleRecord, CustomerNameMap } from '../types.js'
import { fetchSalesList, voidSale } from '../api.js'
import { getCustomerList } from '../../pos/api.js'

// ---------------------------------------------------------------------------
// useSalesHistory — data fetching hook for the sales history page
//
// Encapsulates:
// - Fetching the sales list on mount (with cancellation guard)
// - Customer name lookup cache population
// - Void action with optimistic update
// ---------------------------------------------------------------------------

export interface UseSalesHistoryReturn {
  /** Array of sale records */
  sales: SaleRecord[]
  /** Total count of all sales */
  total: number
  /** Loading state */
  loading: boolean
  /** Error message (null when OK) */
  error: string | null
  /** Currently voiding sale ID (null when idle) */
  voidingId: string | null
  /** Customer lookup cache (id → displayName) */
  customerMap: CustomerNameMap
  /** Void a sale by ID */
  handleVoid: (saleId: string) => Promise<void>
}

export function useSalesHistory(): UseSalesHistoryReturn {
  const [sales, setSales] = useState<SaleRecord[]>([])
  const [total, setTotal] = useState(0)
  const [loading, setLoading] = useState(true)
  const [voidingId, setVoidingId] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  // Customer lookup cache (id → displayName)
  const [customerMap, setCustomerMap] = useState<CustomerNameMap>({})

  // Fetch customer list for name lookups via typed API module
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const customers = await getCustomerList()
        if (!cancelled) {
          const map: CustomerNameMap = {}
          for (const c of customers) {
            map[c.id] = c.displayName
          }
          setCustomerMap(map)
        }
      } catch {
        // Customer lookup failure is non-fatal — will show "Walk-in" fallback
      }
    })()
    return () => { cancelled = true }
  }, [])

  // Fetch sales list on mount
  useEffect(() => {
    let cancelled = false
    ;(async () => {
      setLoading(true)
      setError(null)
      try {
        const data = await fetchSalesList(50)
        if (!cancelled) {
          setSales(data.sales)
          setTotal(data.total)
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : 'Failed to load sales')
        }
      } finally {
        if (!cancelled) setLoading(false)
      }
    })()
    return () => { cancelled = true }
  }, [])

  // Handle void action
  const handleVoid = useCallback(async (saleId: string): Promise<void> => {
    setVoidingId(saleId)
    try {
      await voidSale(saleId)
      // Update the sale in place — only status changes per R13
      setSales((prev) =>
        prev.map((s) => (s.id === saleId ? { ...s, status: 'voided' } : s))
      )
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to void sale')
    } finally {
      setVoidingId(null)
    }
  }, [])

  return { sales, total, loading, error, voidingId, customerMap, handleVoid }
}

