      expect(screen.queryByText(/No line items yet/i)).not.toBeInTheDocument()
    })

    // Try to submit — button is disabled without customer, so this tests the UI state
    const submitButton = screen.getByRole('button', { name: 'Create Order' })
    // Verify it's still disabled (no customer selected)
    expect(submitButton).toBeDisabled()
  })

  it('renders Cancel and Create Order buttons in footer', async () => {
    render(<CreateOrderFormDialog isOpen={true} onClose={() => {}} onSuccess={() => {}} />)

    expect(screen.getByRole('button', { name: 'Cancel' })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Create Order' })).toBeInTheDocument()
  })

  it('disables deposit field when order contains a leased bicycle', async () => {
    // Mock fetch to return isLease=true for the bicycle
    const mockFetch = vi.fn().mockResolvedValue({
      ok: true,
      json: () => Promise.resolve({ bicycle: { id: 'bike-lease-1', isLease: true } }),
    })
    vi.spyOn(global, 'fetch').mockImplementation(mockFetch)

