    fireEvent.change(bikeIdInput, { target: { value: 'bike-lease-1' } })

    // The deposit field should be disabled after the lease check fires
    await waitFor(() => {
      expect(screen.getByText(/Deposit not allowed/i)).toBeInTheDocument()
